function DragAndDrop() {
  const [items, setItems] = useState(['Item 1', 'Item 2']);
  const [draggedItem, setDraggedItem] = useState(null);

  const handleDragStart = (e, index) => {
    setDraggedItem(index);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (e, targetIndex) => {
    e.preventDefault();
    const newItems = [...items];
    const [draggedItemValue] = newItems.splice(draggedItem, 1);
    newItems.splice(targetIndex, 0, draggedItemValue);
    setItems(newItems);
  };

  return (
    <div>
      {items.map((item, index) => (
        <div key={index} draggable onDragStart={(e) => handleDragStart(e, index)} onDragOver={handleDragOver} onDrop={(e) => handleDrop(e, index)}>
          {item}
        </div>
      ))}
    </div>
  );
}

